import React, { useState } from 'react';
import '../styles/MapSection.css';

const MapSection = () => {
    const [mapEnlarged, setMapEnlarged] = useState(false);
    
    const toggleMapSize = (e) => {
        e.preventDefault();
        setMapEnlarged(!mapEnlarged);
    };

    return (
        <section className="map-section">
            <div className="map-container" style={{ height: mapEnlarged ? '800px' : '500px' }}>
                <div className="map-overlay">
                    <img src={`${process.env.PUBLIC_URL}/imgg/Group (2).png`} alt="Карта" className="map-overlay-icon" />
                    <div className="map-overlay-content">
                        <div className="map-overlay-title">Home Space</div>
                        <div className="map-overlay-rating">
                            <div className="map-overlay-stars">★★★★☆</div>
                            <div className="map-overlay-reviews">4.0 (Відгуків: 10)</div>
                        </div>
                    </div>
                </div>
                
                <div className="map-controls">
                    <button>
                        <img src={`${process.env.PUBLIC_URL}/imgg/plus.png`} alt="Збільшити" />
                    </button>
                    <button>
                        <img src={`${process.env.PUBLIC_URL}/imgg/minus.png`} alt="Зменшити" />
                    </button>
                </div>
                
                <a href="#" className="map-enlarge" onClick={toggleMapSize}>
                    {mapEnlarged ? 'зменшити мапу' : 'збільшити мапу'}
                </a>
                
                <iframe
                    src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2573.547024286589!2d30.5234!3d50.4501!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x40d4cf0ee0337a3f%3A0x57a4ddd9446c0bdf!2z0JHRgNCw0YLQvtC90LDRjyDRg9C70LjRhtCw!5e0!3m2!1suk!2sua!4v1620000000000!5m2!1suk!2sua"
                    allowFullScreen=""
                    loading="lazy"
                    title="Home Space Map"
                ></iframe>
            </div>
        </section>
    );
};

export default MapSection;
